+import { promises as fs } from 'node:fs';
+import path from 'node:path';
+import matter from 'gray-matter';
+import { marked } from 'marked';
+
+export interface PageMetadata {
+  title: string;
+  date?: string;
+  tags: string[];
+}
+
+export interface GeneratedPage extends PageMetadata {
+  sourcePath: string;
+  outputPath: string;
+  url: string;
+}
+
+export interface BuildOptions {
+  contentDir?: string;
+  outputDir?: string;
+}
+
+function escapeHtml(value: string): string {
+  return value
+    .replaceAll('&', '&amp;')
+    .replaceAll('<', '&lt;')
+    .replaceAll('>', '&gt;')
+    .replaceAll('"', '&quot;')
+    .replaceAll("'", '&#39;');
+}
+
+function normalizeDate(value: unknown): string | undefined {
+  if (value instanceof Date && !Number.isNaN(value.valueOf())) {
+    return value.toISOString().slice(0, 10);
+  }
+  if (typeof value === 'string' || typeof value === 'number') {
+    return String(value);
+  }
+  return undefined;
+}
+
+function normalizeTags(value: unknown): string[] {
+  if (Array.isArray(value)) {
+    return value.map(String).map((tag) => tag.trim()).filter(Boolean);
+  }
+  if (typeof value === 'string') {
+    return value.split(',').map((tag) => tag.trim()).filter(Boolean);
+  }
+  return [];
+}
+
+async function markdownFiles(directory: string): Promise<string[]> {
+  let entries;
+  try {
+    entries = await fs.readdir(directory, { withFileTypes: true });
+  } catch (error) {
+    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
+      throw new Error(`Content directory does not exist: ${directory}`);
+    }
+    throw error;
+  }
+
+  const files = await Promise.all(entries.map(async (entry) => {
+    const entryPath = path.join(directory, entry.name);
+    if (entry.isDirectory()) return markdownFiles(entryPath);
+    return entry.isFile() && /\.md$/i.test(entry.name) ? [entryPath] : [];
+  }));
+  return files.flat().sort();
+}
+
+function pageTemplate(metadata: PageMetadata, body: string): string {
+  const title = escapeHtml(metadata.title);
+  const date = metadata.date
+    ? `<time datetime="${escapeHtml(metadata.date)}">${escapeHtml(metadata.date)}</time>`
+    : '';
+  const tags = metadata.tags.length
+    ? `<ul class="tags">${metadata.tags.map((tag) => `<li>${escapeHtml(tag)}</li>`).join('')}</ul>`
+    : '';
+
+  return `<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>${title}</title>
+</head>
+<body>
+  <nav><a href="/index.html">Home</a></nav>
+  <main>
+    <article>
+      <header><h1>${title}</h1>${date}${tags}</header>
+      ${body}
+    </article>
+  </main>
+</body>
+</html>
+`;
+}
+
+function indexTemplate(pages: GeneratedPage[]): string {
+  const items = pages.map((page) => {
+    const date = page.date ? ` <time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : '';
+    return `<li><a href="${escapeHtml(page.url)}">${escapeHtml(page.title)}</a>${date}</li>`;
+  }).join('\n      ');
+
+  return `<!doctype html>
+<html lang="en">
+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>Pages</title>
+</head>
+<body>
+  <main>
+    <h1>Pages</h1>
+    <ul>
+      ${items}
+    </ul>
+  </main>
+</body>
+</html>
+`;
+}
+
+export async function buildSite(options: BuildOptions = {}): Promise<GeneratedPage[]> {
+  const contentDir = path.resolve(options.contentDir ?? './content');
+  const outputDir = path.resolve(options.outputDir ?? './dist');
+  const files = await markdownFiles(contentDir);
+
+  await fs.rm(outputDir, { recursive: true, force: true });
+  await fs.mkdir(outputDir, { recursive: true });
+
+  const pages: GeneratedPage[] = [];
+  for (const sourcePath of files) {
+    const source = await fs.readFile(sourcePath, 'utf8');
+    const parsed = matter(source);
+    const relativePath = path.relative(contentDir, sourcePath);
+    const outputRelativePath = relativePath.replace(/\.md$/i, '.html');
+    const outputPath = path.join(outputDir, outputRelativePath);
+    const title = typeof parsed.data.title === 'string' && parsed.data.title.trim()
+      ? parsed.data.title.trim()
+      : path.basename(sourcePath, path.extname(sourcePath));
+    const metadata: PageMetadata = {
+      title,
+      date: normalizeDate(parsed.data.date),
+      tags: normalizeTags(parsed.data.tags),
+    };
+    const body = marked.parse(parsed.content, { async: false }) as string;
+
+    await fs.mkdir(path.dirname(outputPath), { recursive: true });
+    await fs.writeFile(outputPath, pageTemplate(metadata, body), 'utf8');
+    pages.push({
+      ...metadata,
+      sourcePath,
+      outputPath,
+      url: outputRelativePath.split(path.sep).join('/'),
+    });
+  }
+
+  pages.sort((left, right) => left.title.localeCompare(right.title));
+  await fs.writeFile(path.join(outputDir, 'index.html'), indexTemplate(pages), 'utf8');
+  return pages;
+}
*** Add File: src/cli.ts
+#!/usr/bin/env node
+
+import { buildSite, BuildOptions } from './index';
+
+function usage(): string {
+  return 'Usage: ssg build [--content <dir>] [--output <dir>]';
+}
+
+export async function run(argv: string[]): Promise<void> {
+  if (argv[0] !== 'build') {
+    throw new Error(usage());
+  }
+
+  const options: BuildOptions = {};
+  for (let index = 1; index < argv.length; index += 1) {
+    const argument = argv[index];
+    if (argument !== '--content' && argument !== '--output') {
+      throw new Error(`Unknown option: ${argument}\n${usage()}`);
+    }
+    const value = argv[index + 1];
+    if (!value || value.startsWith('--')) {
+      throw new Error(`Missing value for ${argument}\n${usage()}`);
+    }
+    if (argument === '--content') options.contentDir = value;
+    if (argument === '--output') options.outputDir = value;
+    index += 1;
+  }
+
+  const pages = await buildSite(options);
+  process.stdout.write(`Generated ${pages.length} page${pages.length === 1 ? '' : 's'}.\n`);
+}
+
+if (require.main === module) {
+  run(process.argv.slice(2)).catch((error: unknown) => {
+    const message = error instanceof Error ? error.message : String(error);
+    process.stderr.write(`${message}\n`);
+    process.exitCode = 1;
+  });
+}
*** Add File: .gitignore
+node_modules/
+dist/
+coverage/
*** Add File: README.md
+# ssg
+
+A small static site generator that turns Markdown files into HTML pages.
+
+```sh
+npm install
+npm run build
+npx ssg build
+```
+
+Markdown is read from `./content` and HTML is written to `./dist`. Override those directories when needed:
+
+```sh
+npx ssg build --content posts --output public
+```
+
+Frontmatter supports `title`, `date`, and either array or comma-separated `tags`:
+
+```md
+---
+title: Hello
+date: 2026-08-13
+tags: [news, updates]
+---
+
+# Welcome
+```
*** End Patch

